/* Bangla QR recharge (2026-11-06), v1.
   The user's own Bangla QR payment code (their uploaded image, embedded
   as-is so it stays scannable). Shown on #/recharge when the payment
   method is "BanglaQR". The customer scans it with bKash / Nagad /
   Rocket / any bank app, pays, then submits Amount + Transaction ID
   like any other manual recharge — the wallet is credited after the
   admin approves, exactly like bKash/Nagad manual. A static QR has no
   gateway callback, so there is no auto-credit. */
window.NS_BANGLA_QR = 'data:image/jpeg;base64,';
(function () {
  'use strict';
  function sync() {
    try {
      var sel = document.getElementById('rchMethod');
      if (!sel) return;
      var box = document.getElementById('nsBanglaQr');
      if (!box) {
        box = document.createElement('div');
        box.id = 'nsBanglaQr';
        box.innerHTML = '<div class="ns-bqr-card"><img src="' + window.NS_BANGLA_QR + '" alt="বাংলা কিউআর"><p class="ns-bqr-text">বিকাশ, নগদ, রকেট বা যেকোনো ব্যাংকের অ্যাপ দিয়ে QR স্ক্যান করে পেমেন্ট করুন।</p><p class="ns-bqr-note">পেমেন্টের পর নিচে টাকার পরিমাণ ও Transaction ID লিখে জমা দিন — অ্যাডমিন অনুমোদন দিলে ব্যালেন্স যোগ হবে।</p></div>';
        sel.parentNode.insertBefore(box, sel.nextSibling);
      }
      box.style.display = (sel.value === 'BanglaQR') ? '' : 'none';
      if (!sel._nsBqrWired) {
        sel._nsBqrWired = true;
        sel.addEventListener('change', sync);
      }
    } catch (e) {}
  }
  setInterval(sync, 400);
  window.addEventListener('hashchange', function () { setTimeout(sync, 60); });
  document.addEventListener('visibilitychange', function () { if (!document.hidden) sync(); });
})();
